#!/usr/bin/env bash
set -Eeuo pipefail

# CAP04-003: Online Boutique baseline from pinned, unmodified upstream release.
# The upstream file is autogenerated: do not hand-edit the fetched copy.
readonly CTX="k3d-twn-capstone04"
readonly NS="online-boutique"
readonly SOURCE_REPO="asambataiden/twn-devops-bootcamp-10-kubernetes-deploying-microservices-demo"
readonly SOURCE_SHA="218ba3dcef1d19821711e62996162f8b29c55be4"
readonly RELEASE_URL="https://raw.githubusercontent.com/${SOURCE_REPO}/${SOURCE_SHA}/release/kubernetes-manifests.yaml"

die() { printf '[cap04] ERROR: %s\n' "$*" >&2; exit 1; }
log() { printf '[cap04] %s\n' "$*"; }
require() { command -v "$1" >/dev/null 2>&1 || die "Required command not installed: $1"; }

usage() {
  cat <<'HELP'
Usage: bash scripts/capstone04-deploy.sh <fetch|plan|deploy|status>

  fetch   Print pinned upstream artifact URL and download to a temporary file
  plan    Validate environment and server-side dry-run Kubernetes manifests
  deploy  Apply upstream manifests to the dedicated namespace (explicit confirmation)
  status  Inspect current application Deployments, Pods and Services

Important: Requires CAP04-002 local cluster and online-boutique namespace.
No global shell settings are changed; no EKS or banking context is used.
HELP
}

check_target() {
  require kubectl
  require k3d
  k3d cluster get twn-capstone04 >/dev/null 2>&1 || die "Dedicated k3d cluster not found"
  local contexts
  contexts="$(kubectl config get-contexts -o name)" || die "Unable to read kubeconfig"
  grep -Fxq -- "$CTX" <<< "$contexts" || die "Required Kubernetes context missing: $CTX"
  kubectl --context "$CTX" get nodes >/dev/null || die "Target cluster not reachable"
  kubectl --context "$CTX" get namespace "$NS" >/dev/null || die "Namespace '$NS' missing; run CAP04-002 namespace"
  log "Target is explicitly $CTX / $NS"
}

fetch_release() {
  require curl
  local output="$1"
  curl --fail --location --silent --show-error --retry 3 \
    --output "$output" "$RELEASE_URL" || die "Failed to download pinned upstream release"
  test -s "$output" || die "Downloaded artifact empty"
  grep -Fq 'WARNING: This file is autogenerated. Do not manually edit.' "$output" \
    || die "Expected upstream autogenerated-manifest marker absent"
  grep -Fq 'gcr.io/google-samples/microservices-demo/' "$output" \
    || die "Expected versioned microservices image references absent"
  log "Pinned upstream source: $SOURCE_SHA"
}

with_release() (
  local action="$1"
  local tmp
  tmp="$(mktemp)" || die "Unable to create temporary artifact"
  trap 'rm -f "$tmp"' EXIT
  fetch_release "$tmp"
  if [[ "$action" == "fetch" ]]; then
    log "Downloaded and checked pinned source (temporary artifact automatically removed)"
    return
  fi
  check_target
  log "Validating manifest via Kubernetes API dry-run"
  kubectl --context "$CTX" --namespace "$NS" apply \
    --dry-run=server --validate=strict -f "$tmp"
  if [[ "$action" == "plan" ]]; then
    log "Dry-run completed; no application resources created"
    return
  fi
  [[ -t 0 ]] || die "Deployment requires an interactive terminal"
  local answer
  printf 'Type DEPLOY %s/%s to apply these workloads: ' "$CTX" "$NS"
  IFS= read -r answer
  [[ "$answer" == "DEPLOY $CTX/$NS" ]] || die "Confirmation not matched; no deployment"
  kubectl --context "$CTX" --namespace "$NS" apply --validate=strict -f "$tmp"
  log "Deployment submitted; check rollout and resource capacity before claiming success"
  kubectl --context "$CTX" --namespace "$NS" get deployments,pods,services
)

status() {
  check_target
  kubectl --context "$CTX" --namespace "$NS" get deployments,pods,services
}

case "${1:-}" in
  fetch) with_release fetch ;;
  plan) with_release plan ;;
  deploy) with_release deploy ;;
  status) status ;;
  help|--help|-h) usage ;;
  *) usage >&2; exit 2 ;;
esac
